ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_private *priv = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!priv) {
        return -EINVAL;
    }

    mutex_lock(&priv->lock);

    while (bytes_read < count) {
        if (kthread_should_stop()) {
            ret = -ENODEV;
            goto unlock_exit;
        }

        if (priv->queue_empty) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto unlock_exit;
            }

            wait_event_interruptible(priv->wait_queue, !priv->queue_empty);
            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                goto unlock_exit;
            }
        }

        // Assume get_next_timer_data is a helper function to fetch data from the timer queue
        void *data = get_next_timer_data(priv);
        if (!data) {
            ret = -EIO;
            goto unlock_exit;
        }

        if (copy_to_user(buffer + bytes_read, data, sizeof(*data))) {
            ret = -EFAULT;
            goto unlock_exit;
        }

        bytes_read += sizeof(*data);
        priv->queue_empty = queue_is_empty(priv);
    }

    ret = bytes_read;
unlock_exit:
    mutex_unlock(&priv->lock);
    return ret;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_data *data = file->private_data;
    ssize_t bytes_read = 0;
    int result;

    if (!data) {
        return -EFAULT;
    }

    mutex_lock(&data->lock);

    while (bytes_read < count) {
        if (kthread_should_stop()) {
            bytes_read = -EFAULT;
            break;
        }

        if (data->disconnected) {
            bytes_read = -ENODEV;
            break;
        }

        if (data->queue_size == 0) {
            if (file->f_flags & O_NONBLOCK) {
                bytes_read = -EAGAIN;
                break;
            }

            wait_event_interruptible(data->wait_queue, data->queue_size > 0 || data->disconnected);
            continue;
        }

        if (data->queue_size < (count - bytes_read)) {
            count = count - bytes_read;
        }

        result = copy_to_user(buffer + bytes_read, data->queue, data->queue_size);
        if (result != 0) {
            bytes_read = -EFAULT;
            break;
        }

        bytes_read += data->queue_size;
        data->queue = NULL;
        data->queue_size = 0;
    }

    mutex_unlock(&data->lock);
    return bytes_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    struct sound_timer_dev *dev = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!dev)
        return -EFAULT;

    spin_lock(&dev->lock);

    while (bytes_read < (ssize_t)count) {
        if (kthread_should_stop()) {
            ret = -ENODEV;
            goto unlock;
        }

        if (dev->queue_size == 0) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto unlock;
            }

            wait_event_interruptible(dev->read_wait, dev->queue_size > 0);
            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                goto unlock;
            }
        }

        if (dev->queue_size == 0) {
            continue;
        }

        size_t to_read = min(count - bytes_read, (size_t)dev->queue_size);
        if (copy_to_user(buffer + bytes_read, dev->queue, to_read)) {
            ret = -EFAULT;
            goto unlock;
        }

        bytes_read += to_read;
        dev->queue += to_read;
        dev->queue_size -= to_read;

        if (dev->queue_size == 0) {
            wake_up_interruptible(&dev->write_wait);
        }
    }

    ret = bytes_read;
unlock:
    spin_unlock(&dev->lock);
    return ret;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_private *priv;
    ssize_t bytes_read = 0;
    int ret;

    if (!file || !buffer || !offset)
        return -EINVAL;

    priv = file->private_data;
    if (!priv)
        return -EFAULT;

    if (!priv->is_connected)
        return -ENODEV;

    while (count > 0) {
        spin_lock_irq(&priv->lock);

        if (priv->timer_queue_head == priv->timer_queue_tail) {
            spin_unlock_irq(&priv->lock);

            if (file->f_flags & O_NONBLOCK)
                return bytes_read ? bytes_read : -EAGAIN;

            ret = wait_for_data(priv, 0);
            if (ret < 0)
                return bytes_read ? bytes_read : ret;
            continue;
        }

        if (priv->timer_data[priv->timer_queue_tail] == NULL) {
            spin_unlock_irq(&priv->lock);
            break;
        }

        size_t data_size = strlen(priv->timer_data[priv->timer_queue_tail]);
        if (data_size > count)
            data_size = count;

        if (copy_to_user(buffer, priv->timer_data[priv->timer_queue_tail], data_size)) {
            spin_unlock_irq(&priv->lock);
            return -EFAULT;
        }

        bytes_read += data_size;
        count -= data_size;
        buffer += data_size;
        *offset += data_size;

        priv->timer_queue_tail = (priv->timer_queue_tail + 1) % SOUND_TIMER_QUEUE_SIZE;

        spin_unlock_irq(&priv->lock);
    }

    return bytes_read;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_data *st_data = file->private_data;
    ssize_t bytes_read = 0;
    int ret;

    if (!st_data) {
        return -EINVAL;
    }

    spin_lock(&st_data->lock);

    while (bytes_read < count) {
        if (kthread_should_stop() || !st_data->connected) {
            ret = -ENODEV;
            goto unlock_exit;
        }

        if (st_data->queue_empty) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                goto unlock_exit;
            }

            spin_unlock(&st_data->lock);
            wait_for_queue_data(&st_data->wait_queue);
            spin_lock(&st_data->lock);
            continue;
        }

        size_t chunk_size = min(count - bytes_read, st_data->available_bytes);
        if (copy_to_user(buffer + bytes_read, st_data->data, chunk_size)) {
            ret = -EFAULT;
            goto unlock_exit;
        }

        bytes_read += chunk_size;
        advance_queue(st_data, chunk_size);
    }

    ret = bytes_read;

unlock_exit:
    spin_unlock(&st_data->lock);
    return ret;
}
